if(in_array('--local-rollback',$argv,true)){
 if(config('APP_ENV')==='production'||config('DB_DATABASE')!=='rumohub'||!in_array(config('DB_HOST'),['localhost','127.0.0.1','::1'],true))throw new RuntimeException('Somente banco local.');
 $db=Database::connect();$r=new Repository($db);$before=[];foreach(['rumo10_contas','rumo10_carreiras','rumo10_universos'] as $table)$before[$table]=(int)$r->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();$db->beginTransaction();try{
 $r->query('INSERT INTO rumo10_contas(email,senha_hash) VALUES(?,?)',['rn-policy-'.bin2hex(random_bytes(10)).'@example.invalid',password_hash(bin2hex(random_bytes(20)),PASSWORD_DEFAULT)]);$account=(int)$db->lastInsertId();$r->query('INSERT INTO rumo10_carreiras(conta_id,nome,cidade,uf,posicao,idade,etapa,clube) VALUES(?,?,?,?,?,?,?,?)',[$account,'Atleta de teste','Natal','RN','meia',18,'treino','QFC-RN']);$id=(int)$db->lastInsertId();$g['id']=$id;unset($g['state_qualifications'],$g['future_d_admissions']);$r->query('INSERT INTO rumo10_universos(carreira_id,estado_json) VALUES(?,?)',[$id,json_encode($g,JSON_THROW_ON_ERROR)]);$g=$r->load($account);$persistedRows=StateQualification::recordMany($g,array_keys($rows));$persistedAudit=FutureSerieDAdmission::record($g);$r->query('UPDATE rumo10_universos SET estado_json=? WHERE carreira_id=?',[json_encode($g,JSON_THROW_ON_ERROR),$id]);$loaded=$r->load($account);rncheck(StateQualification::recordMany($loaded,array_keys($rows))==$persistedRows,'recibos sobrevivem Repository/PDO e reordenação JSON');$pdoChecks++;rncheck(FutureSerieDAdmission::record($loaded)==$persistedAudit,'admissão pendente idempotente após reload');$pdoChecks++;rncheck($r->load($account+10000000)===null,'conta não proprietária não consulta fixture');$pdoChecks++;
 }finally{if($db->inTransaction())$db->rollBack();}
 foreach($before as $table=>$count){rncheck((int)$r->query('SELECT COUNT(*) FROM '.$table)->fetchColumn()===$count,'rollback '.$table);$pdoChecks++;}
